<?php declare(strict_types=1); namespace App\People\Infrastructure\Persistence\DBAL; use App\People\Domain\Enum\CommunicationChannel; use App\People\Domain\Model\CommunicationOption; use App\People\Domain\Repository\CommunicationOptionRepository; use App\People\Domain\ValueObject\CommunicationOptionId; use App\People\Domain\ValueObject\PersonId; use Doctrine\DBAL\Connection; final readonly class DbalCommunicationOptionRepository implements CommunicationOptionRepository {public function __construct(private Connection $db){} public function save(PersonId $personId,CommunicationOption $o):void{$this->db->beginTransaction();try{if($o->preferred())$this->db->createQueryBuilder()->update('people_communication_options')->set('preferred',':preferred')->where('person_id = :personId')->setParameter('preferred',0)->setParameter('personId',$personId->toString())->executeStatement();$this->db->insert('people_communication_options',['id'=>$o->id()->toString(),'person_id'=>$personId->toString(),'channel'=>$o->channel()->value,'value'=>$o->value(),'preferred'=>$o->preferred()?1:0,'created_at'=>$o->createdAt()->format('Y-m-d H:i:s')]);$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw $e;}} public function delete(CommunicationOptionId $id):void{$this->db->delete('people_communication_options',['id'=>$id->toString()]);} public function findForPerson(PersonId $id):array{$rows=$this->db->createQueryBuilder()->select('c.*')->from('people_communication_options','c')->where('c.person_id = :id')->setParameter('id',$id->toString())->orderBy('c.preferred','DESC')->addOrderBy('c.created_at','ASC')->fetchAllAssociative();return array_map(fn($r)=>CommunicationOption::reconstitute(CommunicationOptionId::fromString($r['id']),CommunicationChannel::from($r['channel']),$r['value'],(bool)$r['preferred'],new \DateTimeImmutable($r['created_at'])),$rows);}}
